<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import {ref,onMounted} from 'vue'
import {request} from '../api'
import ReaderShell from '../blog/ReaderShell.vue'
type Draft={id:string;title:string;summary:string;updated_at:string;type_id:string;type_name:string;type_active:boolean;revision:number;status:string}
const rows=ref<Draft[]>([]),types=ref<{id:string;name:string}[]>([]),q=ref(''),type=ref(''),state=ref(''),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),notice=ref('')
async function load(){busy.value=true;error.value='';try{const params=new URLSearchParams({status:'draft',sort:'updated',q:q.value,page:String(page.value)});if(type.value)params.set('type_id',type.value);if(state.value)params.set('type_state',state.value);const d=await request('/admin/content/records?'+params);rows.value=d.items;total.value=d.total}catch(e){error.value=String(e)}finally{busy.value=false}}
async function remove(r:Draft){if(!await confirmAction('将草稿「'+r.title+'」移入文章回收站？历史修订、媒体和文件夹保留。'))return;busy.value=true;try{await request('/admin/content/records/'+r.id,{method:'DELETE',body:JSON.stringify({expected_revision:r.revision})});notice.value='草稿已进入回收站，未删除原图';await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(async()=>{try{types.value=await request('/admin/content/types')}catch(e){error.value=String(e)}await load()})
</script>
<template><ReaderShell><template #nav><RouterLink to="/write">写文章</RouterLink></template><h1>我的草稿</h1><p>这里显示已成功保存、尚未发布的全部文章类型。草稿不会进入读者文章列表或美食目录。</p><form class="filters" @submit.prevent="page=1;load()"><label>搜索标题<input v-model="q" maxlength="200" type="search"/></label><label>文章类型<select v-model="type"><option value="">全部类型</option><option v-for="t in types" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>状态<select aria-label="草稿状态" v-model="state"><option value="">全部未发布草稿</option><option value="active">类型启用</option><option value="inactive">类型停用（原文保留）</option></select></label><button :disabled="busy">搜索 · 最近修改优先</button></form><p v-if="error" role="alert">{{error}}。已保存内容仍在服务器，可重新加载。</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在读取草稿…</p><p v-else-if="!rows.length">暂无匹配的草稿。<RouterLink to="/write">写下第一篇</RouterLink></p><article v-for="r in rows" :key="r.id" class="archive-row"><h2>{{r.title}}</h2><p>{{r.summary||'尚未填写列表摘要'}}</p><p>{{r.type_name}} · 草稿 · {{new Date(r.updated_at).toLocaleString()}}{{!r.type_active?' · 类型已停用，原文仍保留':''}}</p><div class="actions"><RouterLink :to="'/write/'+r.id">继续编辑</RouterLink><RouterLink :to="'/write/'+r.id+'?publish=1'">编辑并进入发布确认</RouterLink><button type="button" class="danger" :disabled="busy" @click="remove(r)">删除草稿</button></div></article><div class="actions"><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><span>{{page}} · {{total}} 篇</span><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button><button class="quiet" :disabled="busy" @click="load">重新读取已保存草稿</button></div></ReaderShell></template>
